"""Post-run descriptive report, integrity checks and exact original-queue handoff."""
from pathlib import Path
import copy,datetime,hashlib,json
import numpy as np
from PIL import Image
HERE=Path(__file__).resolve().parent;PHASE=HERE.parent;ROOT=HERE.parents[1];OUT=HERE/'results';AUDIT=PHASE/'independent_audit'
def read(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,v):
 with p.open('x') as f:json.dump(v,f,indent=2,allow_nan=False);f.write('\n')
def main():
 plan=read(HERE/'PLAN.json');summary=read(OUT/'SUMMARY.json');profiles=read(OUT/'PROFILE_METRICS.json');pairs=read(OUT/'COMPARISONS.json');audit=read(AUDIT/'NUMERICAL_AUDIT.json');plots=read(OUT/'PLOT_INDEX.json');nxt=read(PHASE/'scientific_review/NEXT_GROUP_METADATA.json');prior=read(ROOT/'work_harps_20261105_c033_context/CONTINUATION_STATE.json')
 for p,h in plan['source_hashes'].items():assert sha(ROOT/p)==h,p
 for p,h in read(OUT/'OUTPUT_HASHES.json').items():assert sha(OUT/p)==h,p
 assert summary['status']=='COMPLETE_FIXED_GROUP_CONTEXT' and audit['status']=='PASS_SEPARATE_C034_NUMERICAL_RECONSTRUCTION'
 counts={};comparisons=[]
 for region in ['core','broad_pattern']:
  bary=[r for r in pairs if r['relationship']=='MERGED_EPOCH_TO_DISCOVERY' and r['frame']=='barycentric' and r['region']==region and not r['identical_product_self_pair']]
  topo={r['dp_id']:r for r in pairs if r['relationship']=='MERGED_EPOCH_TO_DISCOVERY' and r['frame']=='topocentric' and r['region']==region and not r['identical_product_self_pair']}
  assert len(bary)==len(topo)==5
  counts[region]=dict(nonself_observation_reference_pairs=5,higher_barycentric_raw_pearson=sum(r['raw_pearson']>topo[r['dp_id']]['raw_pearson'] for r in bary),lower_barycentric_normalized_rms=sum(r['normalized_rms']<topo[r['dp_id']]['normalized_rms'] for r in bary))
  for r in bary:
   t=topo[r['dp_id']];comparisons.append(dict(region=region,dp_id=r['dp_id'],barycentric_raw_pearson=r['raw_pearson'],topocentric_raw_pearson=t['raw_pearson'],barycentric_normalized_rms=r['normalized_rms'],topocentric_normalized_rms=t['normalized_rms']))
 npz=[]
 for p in sorted(OUT.rglob('*.npz')):
  with np.load(p,allow_pickle=False) as z:
   for k in z.files:assert not z[k].dtype.hasobject
  npz.append(dict(path=str(p.relative_to(OUT)),bytes=p.stat().st_size,sha256=sha(p)))
 assert len(npz)==22
 png=[]
 for r in plots['files']:
  p=OUT/r['path'];assert sha(p)==r['sha256']
  with Image.open(p) as im:im.verify()
  with Image.open(p) as im:im.load();dims=list(im.size)
  png.append(dict(path=r['path'],dimensions=dims,sha256=sha(p)))
 assert len(png)==4
 qa=dict(status='PASS_C034_DELIVERY_QA',source_hashes_unchanged=len(plan['source_hashes']),npz_containers_decoded=npz,png_figures_decoded=png,all_profiles_full_raw_and_normalized_support=all(r['raw_grid_finite_samples']==r['normalized_grid_finite_samples']==601 for r in profiles),positive_references=len([r for r in profiles if r.get('flank_reference',0)>0]),low_reference_flags=sum(r.get('low_flank_reference') is True for r in profiles),profiles_with_nonpositive_original_samples=sum(r.get('window_nonpositive_fraction',0)>0 for r in profiles),evaluable_raw_pearson_rows=sum(r['raw_pearson'] is not None for r in pairs),evaluable_normalized_rms_rows=sum(r['normalized_rms'] is not None for r in pairs),counts=counts,comparison_detail=comparisons,labels_changed=0,origin_assignments=0,visual_review_path='scientific_review/VISUAL_REVIEW.json')
 write(HERE/'RESULTS_QA.json',qa)
 write(PHASE/'scientific_review/VISUAL_REVIEW.json',dict(status='PASS_ALL_FOUR_FIXED_FIGURES_INSPECTED',reviewer_scope='Same assistant using direct image inspection; no independent agent or human review.',files=png,observations=['The full neighboring pattern and rounded central feature align across epochs in barycentric coordinates after separate flank scaling.','In fixed topocentric coordinates the same structures move across the window. Adjacent May dates retain greater visual similarity than separated dates.','The own native19 extraction and same-epoch merged spectrum share the broad pattern. They are dependent extractions of one exposure.','The original raw19 panel retains the diffuse trace-centered excess and bright right-edge structure at full stored scale. No new background subtraction,registration,crop or physical attribution.'],figure_variants_added=0,classification='U',qualified_laser_candidate=False))
 lines=['# C034 / HD126093: completed singleton profile context','', '**V2E2-0271 remains U. No qualified laser candidate or physical origin is established.**','', 'Six existing April–July2025 observations, one own May29 discovery reference, native order19 and the original raw19 container produced **14 profiles and28 comparisons**. Exact original center4312.202499999999airÅ; own BERV -8.31835117513205km/s fixes the topocentric anchor4312.322154144395airÅ. No observing time was added.','', '## Frame comparison','', '| Region | Higher barycentric raw Pearson r | Lower barycentric normalized RMS |','|---|---:|---:|']
 for name,r in counts.items():lines.append(f"| {name} | {r['higher_barycentric_raw_pearson']}/5 | {r['lower_barycentric_normalized_rms']}/5 |")
 lines+=['','Per region/frame these are five different nonself observation/reference pairs among only six observations, with no reciprocal pairs. Four identical-product self rows and four same-exposure native-to-merged rows remain labeled in the full28 rows. They do not add independent confirmation.','', 'Both the rounded central feature and neighboring pattern align best barycentrically. This is consistent with stable stellar spectral structure; it does not identify a specific transition, establish the physical cause, measure a linewidth or qualify an artificial laser. All original U/U/U dispositions remain unchanged.','', '| Region | Observation product | Barycentric r | Topocentric r | Barycentric RMS | Topocentric RMS |','|---|---|---:|---:|---:|---:|']
 for r in comparisons:lines.append(f"| {r['region']} | {r['dp_id']} | {r['barycentric_raw_pearson']:.9f} | {r['topocentric_raw_pearson']:.9f} | {r['barycentric_normalized_rms']:.9f} | {r['topocentric_normalized_rms']:.9f} |")
 lines+=['','## Coverage and original evidence','','All14 profiles have601 finite raw and normalized grid samples, positive flank references and no low-reference flag. None of the current bounded windows contains nonpositive original flux samples. All28 correlation and RMS rows are evaluable. ERR has no positive finite support. These are measured current outcomes, not quality inherited from C033.','', 'Freshly scanning all72 native order headers selects only order19. Its original global/local/baseline/later mapping stages are true and remain separate. The original raw19 container is preserved byte for byte. The own0271 secondary review has no recorded blend caution; the C0330274 caution is not transferred. Fourteen original-member support records retain the exact barycentric and discovery-topocentric core bounds.','', 'Signed structured flanks are not certified continua. Merged flux is uncalibrated ADU; native units are unspecified. Separate divisors and difference-noise proxies do not supply calibrated significance, sensitivity, physical flux ratios or linewidth.','', 'The six merged physical sources are shared with C033, but all current source-index windows are disjoint from their C033 windows. Native order19 is an additional context from the already reused May exposure. Prior epoch/raw values were exposed; disjoint windows do not establish blind or independent validation.','', '## Verification and publication','', f"Input/header audit:175 checks over72 native orders. Synthetic preflight:101 checks. Separate scalar prospective checks:1449 over73010 values. Observed reconstruction:**{audit['checks_passed']} checks over{audit['scalar_values_compared']:,} numerical values**. All22 NPZ containers and four fixed PNGs decode; the same assistant inspected every figure. No independent agent/human review is claimed.",'', 'All20 public method files were compared byte for byte before current observed arithmetic, and the public tree blob identities were verified. The plan, release and all46 source bindings remain unchanged. The scientific calculation ran once; original outputs refuse overwrite. Results and subsequent descriptive reporting do not turn earlier data into a blind experiment.','', '## Exact next original route','', 'C032 is next by original queue row80, with V2E2-0278 and0283 and their own June27/July16 references. Original centers3869.2975 and3869.295airÅ remain separate; proposed metadata midpoint3869.2962500000003airÅ is not a fitted or frozen next diagnostic. Restore their own native/raw products, fresh72-order header scans and own geometry/quality handling. Do not transfer current order19, support or anchor.','', 'Completed routes remain closed despite physical U. Rubin remains STOPPED_LIMITED_FEASIBILITY_MINIMUM50_UNMET. No background science job is running.','', '## Fixed scientific figures','']
 for r in plots['files']:lines+=['!['+Path(r['path']).stem+'](results/'+r['path']+')','']
 (HERE/'RESULTS_REPORT.md').write_text('\n'.join(lines)+'\n')
 write(PHASE/'NEXT_ACTION.json',{**nxt,'created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'current_phase_closed':str((PHASE/'GROUP_CLOSURE.json').relative_to(ROOT)),'new_diagnostic_executed':False,'no_background_execution':True,'standing_authorization':'User approved publication and requested autonomous continuation in the same public SETI repository.'})
 closure=dict(schema='HARPS_C034_CLOSURE_V1',status='COMPLETE_FIXED_CONTEXT_U_UNCHANGED',events=['V2E2-0271'],profiles=14,comparisons=28,observations=6,distinct_discovery_products=1,counts=counts,qualified_laser_candidate=False,physical_origin_assigned=False,source_hashes_unchanged=True,production_executions=1,observed_audit_checks=audit['checks_passed'],observed_audit_scalar_values=audit['scalar_values_compared'],figures_inspected=4,npz_containers_decoded=22,next_group='C032',no_background_science_job=True)
 write(PHASE/'GROUP_CLOSURE.json',closure)
 state=copy.deepcopy(prior);state.update(schema='HARPS_C034_CONTINUATION_STATE_V1',created_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),entry_point='CONTINUE_SETI.md',previous_continuation_state='work_harps_20261105_c033_context/CONTINUATION_STATE.json',previous_continuation_state_sha256=sha(ROOT/'work_harps_20261105_c033_context/CONTINUATION_STATE.json'),completed_original_routes=sorted(set(prior['completed_original_routes'])|{'C034'}),next_action=str((PHASE/'NEXT_ACTION.json').relative_to(ROOT)),completed_harps_c034_context=closure,science=dict(target='HD126093',current_phase='C034',physical_labels_unchanged=True,qualified_laser_candidates=0,added_observing_time=0),publication=dict(authorization_path=str((PHASE/'PUBLICATION_AUTHORIZATION.json').relative_to(ROOT)),method_commit=read(HERE/'ROOT_RELEASE.json')['publication_commit'],method_readback_files=20,result_publication_status='PENDING_EXACT_RESULT_TREE_VERIFICATION'),integration=dict(status='PENDING_FINAL_HEAD_CI_AND_GUARDED_MERGE',instruction='Verify live refs/PR; creation-time pending fields do not assert later integration.'),execution=dict(science_background_jobs=0,production_executions=1))
 state['source_hashes']={str(f.relative_to(ROOT)):sha(f) for f in [PHASE/'NEXT_ACTION.json',PHASE/'GROUP_CLOSURE.json',HERE/'RESULTS_QA.json',HERE/'RESULTS_REPORT.md',AUDIT/'NUMERICAL_AUDIT.json']};state['source_hashes'].update(plan['source_hashes']);write(PHASE/'CONTINUATION_STATE.json',state)
 report='work_harps_20261105_c034_context/analysis/RESULTS_REPORT.md'
 (PHASE/'README.md').write_text('# C034 / HD126093: complete\n\nOne original record, six existing observations,14profiles and28comparisons. Both core and surroundings favor barycentric correlation and normalized RMS in all5nonself comparisons. Physical U remains; no qualified laser.\n\n[Report and four figures](analysis/RESULTS_REPORT.md) · [Numerical audit](independent_audit/NUMERICAL_AUDIT.json) · [Closure](GROUP_CLOSURE.json) · [Next C032](NEXT_ACTION.json) · [State](CONTINUATION_STATE.json).\n\nNo added observing time, blind validation or independent agent/human review. Verify live publication and CI before integration.\n')
 top='## SETI-status — C034 på HD126093 afsluttet (5. november2026)\n\n**Én post, seks eksisterende observationer,14profiler og28sammenligninger. Fortsat uafklaret; ingen kvalificeret laserkandidat.**\n\nKernen og det omgivende spektralmønster passer bedst barycentrisk i alle5andre-observationspar, både målt med korrelation og normaliseret RMS. Alle14profiler har fuld dækning og positive referencer uden lav-referenceflag. Separat efterregning består1184kontroller over55.139talværdier. Fire figurer er inspiceret.\n\n[Fortsæt her](CONTINUE_SETI.md) · [Rapport og figurer]('+report+') · [Aktuel tilstand](work_harps_20261105_c034_context/CONTINUATION_STATE.json). Næste oprindelige køpunkt er C032 med to poster og egne juni/julireferencer. Tidligere statusafsnit nedenfor er historiske. Ingen baggrundssøgning kører.\n\n---\n\n'
 p=ROOT/'README.md';p.write_text(top+p.read_text())
 top='# Continue SETI from completed C034 / HD126093\n\nRead [the current state](work_harps_20261105_c034_context/CONTINUATION_STATE.json), verify live refs and source hashes, and resume [the exact C032 handoff](work_harps_20261105_c034_context/NEXT_ACTION.json).\n\nC034 is complete: singleton0271, own May29 reference, six reused observations,14profiles and28comparisons. Core and surroundings each favor barycentric correlation and RMS in all5nonself pairs. All14profiles have601finite raw/normalized samples and positive references; no low-reference or nonpositive-source flags. Own order19 and raw19 context and original U/U/U chain remain. No physical cause, qualified laser, blind validation or calibrated survey null.\n\nPublic20-file method readback preceded current arithmetic. Separate scalar reconstruction passes1184checks over55,139values;22NPZcontainers and4fixed figures decode and all figures were inspected by the same assistant. Six physical merged sources recur from C033 with disjoint current source windows; own native19 is an additional context from an existing observation. Reused exposures remain dependent.\n\nExact next original route is C032, first queue row80, records0278/0283 with own June27 andJuly16 references, exact centers3869.2975/3869.295airÅ. Proposed metadata midpoint3869.2962500000003Å is not the next frozen method. Restore own native/raw sources, scan all72orders per product and freeze own original/common geometry and quality; do not inherit current order19, support, anchor or morphology.\n\nThe user directly approved public release and continued GitHub updates. Publish exact results, verify final-head CI, merge with expected-head guards and synchronize optical-harps-week-20261101. Confirm actual live state: creation-time receipts do not assert later integration. Completed routes stay closed despite U. Rubin remains STOPPED_LIMITED_FEASIBILITY_MINIMUM50_UNMET; no background science job is running.\n\n[Report and four figures]('+report+'). All prior sections below are historical.\n\n---\n\n'
 p=ROOT/'CONTINUE_SETI.md';p.write_text(top+p.read_text())
 print(json.dumps(dict(status=qa['status'],profiles=14,comparisons=28,counts=counts,npz_containers=22,figures=4,next_group='C032'),indent=2))
